static long insertOrderAndReturnId(Connection conn, String customerName, BigDecimal total) throws SQLException {
  try (PreparedStatement ps = conn.prepareStatement("INSERT INTO orders (customer_name, total_amount) VALUES (?,?)", Statement.RETURN_GENERATED_KEYS)) {
    ps.setString(1, customerName); ps.setBigDecimal(2, total);
    ps.executeUpdate();
    try (ResultSet keys = ps.getGeneratedKeys()) { keys.next(); return keys.getLong(1); }
  }
}

