static long createOrderWithItems(Connection conn, String customerName, List<String> productNames) throws SQLException {
  long orderId = insertOrderAndReturnId(conn, customerName, BigDecimal.ZERO);
  for (String product : productNames) {
    try (PreparedStatement ps = conn.prepareStatement("INSERT INTO order_items (order_id, product_name) VALUES (?,?)")) {
      ps.setLong(1, orderId); ps.setString(2, product); ps.executeUpdate();
    }
  }
  return orderId;
}

