class OrderRepository {
  private final Connection conn;
  OrderRepository(Connection conn) { this.conn = conn; }
  String create(String customerName, BigDecimal total) throws SQLException {
    long id = insertOrderAndReturnId(conn, customerName, total);
    try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM orders WHERE id=?")) {
      ps.setLong(1, id);
      try (ResultSet rs = ps.executeQuery()) { rs.next(); return rs.getInt("id") + ": " + rs.getString("customer_name"); }
    }
  }
}

